"use client";

import { forwardRef } from "react";
import {
  DateInput,
  DateSegment,
  FieldError,
  Label,
  Text,
  TimeField as AriaTimeField,
  type TimeFieldProps as AriaTimeFieldProps,
  type TimeValue,
} from "react-aria-components";
import { timeFieldDefaults, type TimeFieldSpecProps } from "../generated/time-field.types";
import { cx } from "../utils/cx";
import { fieldGroup, fieldGroupSizes, segment, tidySegment } from "../utils/field";

export interface TimeFieldProps
  extends TimeFieldSpecProps,
    Omit<AriaTimeFieldProps<TimeValue>, keyof TimeFieldSpecProps | "className" | "children"> {
  className?: string;
}

export const TimeField = forwardRef<HTMLDivElement, TimeFieldProps>(function TimeField(
  {
    label,
    description,
    errorMessage,
    granularity = timeFieldDefaults.granularity,
    size = timeFieldDefaults.size,
    isDisabled = timeFieldDefaults.isDisabled,
    // Left undefined unless passed: React Aria treats any defined isInvalid as
    // controlled and would hide its own validation (min and max times, required).
    isInvalid,
    isRequired = timeFieldDefaults.isRequired,
    className,
    ...rest
  },
  ref,
) {
  return (
    <AriaTimeField
      {...rest}
      ref={ref}
      granularity={granularity}
      isDisabled={isDisabled}
      isInvalid={isInvalid}
      isRequired={isRequired}
      className={cx("flex flex-col gap-2", className)}
    >
      <Label className="text-sm font-medium text-[var(--rd-color-text-default)]">
        {label}
        {isRequired && <span aria-hidden="true" className="text-[var(--rd-color-feedback-danger)]"> *</span>}
      </Label>
      <DateInput className={cx(fieldGroup, fieldGroupSizes[size], "tabular-nums")}>
        {(seg) => <DateSegment segment={tidySegment(seg)} className={segment} />}
      </DateInput>
      {description && (
        <Text slot="description" className="text-xs text-[var(--rd-color-text-muted)]">
          {description}
        </Text>
      )}
      <FieldError className="text-xs text-[var(--rd-color-feedback-danger)]">{errorMessage}</FieldError>
    </AriaTimeField>
  );
});

// Generated by rdloom codegen from specs/time-field.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const timeFieldGranularityValues = ["hour", "minute", "second"] as const;
export const timeFieldSizeValues = ["sm", "md", "lg"] as const;

/** A field for a time of day, with separate hour, minute and (optional) second segments that follow the visitor's locale and 12 or 24 hour clock. */
export interface TimeFieldSpecProps {
  /**
   * Visible label, also the accessible name.
   */
  label: string;
  /**
   * Help text under the field.
   */
  description?: string;
  /**
   * Shown when the value is invalid. Leave out to use the built-in message.
   */
  errorMessage?: string;
  /**
   * Controlled value.
   */
  value?: import("react-aria-components").TimeValue | null;
  /**
   * Initial value when uncontrolled.
   */
  defaultValue?: import("react-aria-components").TimeValue | null;
  /**
   * Called with the time, or null when it is cleared.
   */
  onChange?: (value: import("react-aria-components").TimeValue | null) => void;
  /**
   * Smallest unit shown and edited.
   * @default "minute"
   */
  granularity?: "hour" | "minute" | "second";
  /**
   * Force a 12 or 24 hour clock. Leave out to follow the locale.
   */
  hourCycle?: 12 | 24;
  /**
   * Earliest allowed time.
   */
  minValue?: import("react-aria-components").TimeValue;
  /**
   * Latest allowed time.
   */
  maxValue?: import("react-aria-components").TimeValue;
  /**
   * Field height and text size.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Prevents interaction and dims the field.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Marks the field invalid. Leave it unset to let validation decide.
   */
  isInvalid?: boolean;
  /**
   * Marks the field required and adds an asterisk.
   * @default false
   */
  isRequired?: boolean;
}

export const timeFieldDefaults = {
  granularity: "minute",
  size: "md",
  isDisabled: false,
  isRequired: false,
} as const;

export const timeFieldMeta = {
  "name": "TimeField",
  "version": "0.1.0",
  "status": "experimental",
  "role": "group"
} as const;
